import{_ as o,o as a,c as r,a8 as e}from"./chunks/framework.BppdKxCY.js";const q=JSON.parse('{"title":"EP.37 AI 协作工程化","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.37-ai-collaboration.md","filePath":"comics/EP.37-ai-collaboration.md","lastUpdated":1792817913000}'),l={name:"comics/EP.37-ai-collaboration.md"};function d(i,t,n,s,h,c){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="ep-37-ai-协作工程化" tabindex="-1">EP.37 AI 协作工程化 <a class="header-anchor" href="#ep-37-ai-协作工程化" aria-label="Permalink to &quot;EP.37 AI 协作工程化&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../24-ai-collaboration">24-ai-collaboration.md</a> 24.1~24.7 节 · 示例：<code>examples/24-01-ai-collab-contract.ts</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：像素酱的困惑——AI 写的代码&quot;又快又像样&quot;，一上线就炸。本项目门禁首跑即实证：68 条&quot;看起来对&quot;的实跑命令里抓出 4 条真实失败，外加装饰器语义漂移、224 处历史锚点错位、浏览器专属示例误标可直跑——全藏在人眼会跳过的细节里。</li><li><strong>第 2 格</strong>：码叔摊开四阶段流水线：① 契约定义（人主导）→ ② AI 生成（结构化提示词）→ ③ 迭代修复（失败原文喂回）→ ④ 质量验收（门禁主导），验收不过回到 ③ 甚至 ①，形成闭环。主导权各归其位，越权即失控。</li><li><strong>第 3 格</strong>：标签君实证&quot;契约即提示词&quot;——把需求写成 AI 可执行的规格：类型签名 + 用例表 + 不变量。<code>parseSseLine</code> 契约 6 用例 + 3 不变量，v1 被击穿 4 项，失败报告原文喂回后 v2 全绿。</li><li><strong>第 4 格</strong>：码叔结案三级门禁——L0 静态关（typecheck/lint）、L1 行为关（单测/示例实跑）、L2 集成关（全站构建/回归）。机器验收，不靠人眼感觉。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-为什么人眼验收追不上-ai" tabindex="-1">第 1 格 · 为什么人眼验收追不上 AI <a class="header-anchor" href="#第-1-格-·-为什么人眼验收追不上-ai" aria-label="Permalink to &quot;第 1 格 · 为什么人眼验收追不上 AI&quot;">​</a></h3><p>AI 参与编码后，工程师的核心产出从「代码本身」迁移到「契约能力」。AI 的三个工程特征决定了这一点：<strong>速度极快且无记忆</strong>（每次会话都是新人入职）、<strong>自信地犯错</strong>（幻觉 API、静默吞异常，错误藏得很深）、<strong>对约束极其敏感</strong>（给足约束质量飙升，一句话需求自由发挥）。量级与深度的双重不匹配，决定了验收必须是机器行为——本项目自己的五关门禁就是活例子。</p><h3 id="第-2-格-·-四阶段流水线" tabindex="-1">第 2 格 · 四阶段流水线 <a class="header-anchor" href="#第-2-格-·-四阶段流水线" aria-label="Permalink to &quot;第 2 格 · 四阶段流水线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>主导</th><th>产出物</th></tr></thead><tbody><tr><td>① 契约定义</td><td>人</td><td>类型签名 + 用例表 + 不变量</td></tr><tr><td>② AI 生成</td><td>AI</td><td>结构化提示词驱动的一次性完整实现</td></tr><tr><td>③ 迭代修复</td><td>人+AI</td><td>失败输出原文喂回，1~3 轮收敛</td></tr><tr><td>④ 质量验收</td><td>门禁</td><td>L0/L1/L2 三级机器验收</td></tr></tbody></table><p>任何阶段越权——人替 AI 写实现、AI 自己验收自己——都会让质量失控。验收不过时回到 ③ 修复；连续 3 轮不收敛，说明契约或任务拆分有问题，回到 ① 改契约。</p><h3 id="第-3-格-·-契约三要素" tabindex="-1">第 3 格 · 契约三要素 <a class="header-anchor" href="#第-3-格-·-契约三要素" aria-label="Permalink to &quot;第 3 格 · 契约三要素&quot;">​</a></h3><p>契约 = 类型签名 + 输入输出用例表 + 不变量，三者都是&quot;AI 可执行&quot;的规格：</p><ol><li><strong>类型签名</strong>：TS 类型即文档即编译期测试，<code>Result&lt;T&gt;</code> 联合强制处理失败路径；</li><li><strong>用例表</strong>：输入 + 期望输出 + 一句话描述，必须含边界用例（空输入、非法 JSON、超长内容）——历史 bug 是最好的边界来源；</li><li><strong>不变量</strong>：对所有输入都成立的性质（如&quot;任何输入不得抛异常&quot;），补用例表覆盖不到的洞。</li></ol><p>隐藏收益：契约写完，需求歧义就消除了——很多&quot;AI 写错了&quot;本质是需求没想清楚。修复阶段必须<strong>锁范围</strong>：明确&quot;只许改实现函数，契约与测试不许动&quot;，防止 AI 顺手&quot;修复&quot;用例表来让测试通过。</p><h3 id="第-4-格-·-三级门禁" tabindex="-1">第 4 格 · 三级门禁 <a class="header-anchor" href="#第-4-格-·-三级门禁" aria-label="Permalink to &quot;第 4 格 · 三级门禁&quot;">​</a></h3><table tabindex="0"><thead><tr><th>级别</th><th>名称</th><th>内容</th><th>拦截的问题</th></tr></thead><tbody><tr><td>L0</td><td>静态关</td><td>typecheck、lint、格式</td><td>幻觉 API、类型错误、风格漂移</td></tr><tr><td>L1</td><td>行为关</td><td>单测、示例实跑、契约符合性</td><td>逻辑错误、边界缺失、运行时崩溃</td></tr><tr><td>L2</td><td>集成关</td><td>全站构建、E2E、回归对比</td><td>破坏其他模块、集成失败</td></tr></tbody></table><p>门禁三原则：<strong>幂等且离线可跑</strong>（依赖网络的验收会被人跳过）；<strong>失败输出就是修复提示词</strong>（报错写到能直接喂给 AI 的程度）；<strong>宁可误报不可漏报</strong>（误报耗一次判断，漏报耗一次事故）。L1 不能替代 L2——模块间交互问题（路由变更、锚点错位）只有全站构建能暴露。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../24-ai-collaboration#_24-9-本章避坑清单">《24.9 本章避坑清单》</a></p></blockquote><ol><li><strong>别让 AI 直接 push 到 main</strong>：人审 + 门禁双重通过才可合入；</li><li><strong>失败输出原文喂回，别转述人话</strong>：人话转述是二次压缩会引入新歧义，AI 可能据此改错位置；</li><li><strong>防 AI 顺手改用例表</strong>：锁范围提示词 + diff 审查必查&quot;用例表/常量/配置是否被改&quot; + 契约文件 code owner 保护；</li><li><strong>先写门禁再生成</strong>：没有客观验收标准的任务不托管给 AI——不能验收的任务（纯探索、视觉审美）只适合&quot;AI 出候选、人做决策&quot;。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li><strong>四阶段中哪个阶段必须由人主导？为什么？</strong>——契约定义。需求只有人懂，契约是&quot;什么算对&quot;的客观判据；契约交给 AI 写等于让 AI 自己定验收标准，后续生成与修复都失去锚点。其余阶段：生成归 AI（量大速度快）、修复归人机对话（失败喂回）、验收归门禁（不靠感觉）。</li><li><strong>用例表和不变量为什么两者都要？</strong>——用例表是点状验证（给定输入断言输出），精确定义&quot;什么算对&quot;但覆盖有限；不变量是面状验证（对所有输入成立的性质），AI 可以过全部用例却在未覆盖输入上抛异常，不变量补的正是这个洞。</li><li><strong>&quot;先确认门禁存在，再让 AI 生成&quot;背后的逻辑是什么？</strong>——门禁是任务的验收标准，先于生成存在意味着：(a) 需求必须先写成可客观判定的形式，歧义在生成前消除；(b) AI 产出从第一行起就在可验收轨道上，迭代修复有明确终止条件；(c) 避免&quot;生成完再补测试&quot;时测试被实现细节反向污染。</li></ol>',22)])])}const g=o(l,[["render",d]]);export{q as __pageData,g as default};
